static void boot_fn(void *a, void *b, void *c) {
    k_busy_wait(5000);   /* 5 ms of radio init */
    k_msleep(100);
}
static void ctl_fn(void *a, void *b, void *c) {
    k_msleep(1);
    woke_at = k_uptime_get();
}
K_THREAD_DEFINE(boot, 1024, boot_fn, NULL, NULL, NULL, -1, 0, 0);
K_THREAD_DEFINE(ctl,  1024, ctl_fn,  NULL, NULL, NULL,  0, 0, 0);
